    public static string T(string value, string language) => language == "id" ? Texts.GetValueOrDefault(value, value) : value;
    public static string Status(OperationStatus value, string language) => T(value.ToString(), language);
    public static string CommandName(CommandDefinition command, string language) { var index = Catalog.Commands.ToList().FindIndex(c => c.Id == command.Id); return language == "id" && index >= 0 && index < Names.Length ? Names[index] : command.Name; }
    public static string Consequence(CommandDefinition command, string language) => language == "id" ? (command.ReadOnly ? "Mengumpulkan informasi. Windows dapat menulis log operasional." : "Tindakan ini dapat mengubah Windows atau membuka alat administrasi. Tinjau rincian teknis sebelum melanjutkan.") + "\n\n" + command.Consequences : command.Consequences;
